CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),username text UNIQUE NOT NULL,email text UNIQUE NOT NULL,password_hash text NOT NULL,display_name text NOT NULL,account_type text NOT NULL DEFAULT 'PERSONAL',role text NOT NULL DEFAULT 'USER',verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),author_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,caption text NOT NULL DEFAULT '',visibility text NOT NULL DEFAULT 'PUBLIC',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,url text NOT NULL,media_type text NOT NULL,width int,height int,duration_ms int,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS post_media(post_id uuid REFERENCES posts(id) ON DELETE CASCADE,media_id uuid REFERENCES media_assets(id) ON DELETE CASCADE,position int NOT NULL DEFAULT 0,PRIMARY KEY(post_id,media_id));
CREATE TABLE IF NOT EXISTS post_likes(post_id uuid REFERENCES posts(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(post_id,user_id));
CREATE TABLE IF NOT EXISTS comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),post_id uuid REFERENCES posts(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS follows(follower_id uuid REFERENCES users(id) ON DELETE CASCADE,following_id uuid REFERENCES users(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(follower_id,following_id),CHECK(follower_id<>following_id));
CREATE TABLE IF NOT EXISTS shops(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid UNIQUE REFERENCES users(id) ON DELETE CASCADE,name text NOT NULL,slug text UNIQUE NOT NULL,description text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shop_id uuid REFERENCES shops(id) ON DELETE CASCADE,name text NOT NULL,slug text UNIQUE NOT NULL,description text NOT NULL DEFAULT '',price bigint NOT NULL,stock int NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id) ON DELETE CASCADE,type text NOT NULL,title text NOT NULL,body text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_posts_created ON posts(created_at DESC); CREATE INDEX IF NOT EXISTS idx_comments_post ON comments(post_id,created_at); CREATE INDEX IF NOT EXISTS idx_products_shop ON products(shop_id);
